     6	/**
     7	 * Calculates the amount per user given a list of participants
     8	 *
     9	 * @param numberOfParticipants - Number of participants in the chat. It should not include the current user.
    10	 * @param total - IOU total amount in backend format (cents, no matter the currency)
    11	 * @param currency - This is used to know how many decimal places are valid to use when splitting the total
    12	 * @param isDefaultUser - Whether we are calculating the amount for the current user
    13	 */
    14	function calculateAmount(numberOfParticipants: number, total: number, currency: string, isDefaultUser = false): number {
    15	    // Since the backend can maximum store 2 decimal places, any currency with more than 2 decimals
    16	    // has to be capped to 2 decimal places
    17	    const currencyUnit = Math.min(100, CurrencyUtils.getCurrencyUnit(currency));
    18	    const totalInCurrencySubunit = Math.round((total / 100) * currencyUnit);
    19	    const totalParticipants = numberOfParticipants + 1;
    20	    const amountPerPerson = Math.round(totalInCurrencySubunit / totalParticipants);
    21	    let finalAmount = amountPerPerson;
    22	    if (isDefaultUser) {
    23	        const sumAmount = amountPerPerson * totalParticipants;
    24	        const difference = totalInCurrencySubunit - sumAmount;
    25	        finalAmount = totalInCurrencySubunit !== sumAmount ? amountPerPerson + difference : amountPerPerson;
    26	    }
    27	    return Math.round((finalAmount * 100) / currencyUnit);
    28	}
    29	
    30	/**
    31	 * The owner of the IOU report is the account who is owed money and the manager is the one who owes money!
    32	 * In case the owner/manager swap, we need to update the owner of the IOU report and the report total, since it is always positive.
    33	 * For example: if user1 owes user2 $10, then we have: {ownerAccountID: user2, managerID: user1, total: $10 (a positive amount, owed to user2)}
    34	 * If user1 requests $17 from user2, then we have: {ownerAccountID: user1, managerID: user2, total: $7 (still a positive amount, but now owed to user1)}
    35	 *
    36	 * @param isDeleting - whether the user is deleting the request
    37	 */
    38	function updateIOUOwnerAndTotal(iouReport: Report, actorAccountID: number, amount: number, currency: string, isDeleting = false): Report {
    39	    if (currency !== iouReport.currency) {
    40	        return iouReport;
    41	    }
    42	
    43	    // Make a copy so we don't mutate the original object
    44	    const iouReportUpdate: Report = {...iouReport};
    45	
    46	    if (iouReportUpdate.total) {
    47	        if (actorAccountID === iouReport.ownerAccountID) {
    48	            iouReportUpdate.total += isDeleting ? -amount : amount;
    49	        } else {
    50	            iouReportUpdate.total += isDeleting ? amount : -amount;
    51	        }
    52	
    53	        if (iouReportUpdate.total < 0) {
    54	            // The total sign has changed and hence we need to flip the manager and owner of the report.
    55	            iouReportUpdate.ownerAccountID = iouReport.managerID;
    56	            iouReportUpdate.managerID = iouReport.ownerAccountID;
    57	            iouReportUpdate.total = -iouReportUpdate.total;
    58	        }
    59	
    60	        iouReportUpdate.hasOutstandingIOU = iouReportUpdate.total !== 0;
    61	    }
    62	
    63	    return iouReportUpdate;
    64	}
